-- The LandSandBoat species behind every Trust.
--
-- Generated by tools/import_lsb_trusts.py from mob_pools.speciesid.  293..297 are
-- the five player races (Elvaan, Galka, Hume, Mithra, Tarutaru); game/trust_stats.py
-- uses that to pick the racial base HP/MP curve.  Any other species keeps the Hume
-- fallback.  295 is the default because it is the common species.
ALTER TABLE trusts ADD COLUMN species INTEGER NOT NULL DEFAULT 295;

UPDATE trusts SET species = 49 WHERE spell_id IN (989);
